pub fn build_blob_data_column_sidecars<T: BeaconChainTypes>(
    chain: &BeaconChain<T>,
    block: &SignedBeaconBlock<T::EthSpec, FullPayload<T::EthSpec>>,
    blobs: BlobsList<T::EthSpec>,
    kzg_cell_proofs: KzgProofs<T::EthSpec>,
) -> Result<DataColumnSidecarList<T::EthSpec>, DataColumnSidecarError> {
    // Only attempt to build data columns if blobs is non empty to avoid skewing the metrics.
    if blobs.is_empty() {
        return Ok(vec![]);
    }

    let mut timer = metrics::start_timer_vec(
        &metrics::DATA_COLUMN_SIDECAR_COMPUTATION,
        &[&blobs.len().to_string()],
    );
    let blob_refs = blobs.iter().collect::<Vec<_>>();
    let sidecars = blobs_to_data_column_sidecars(
        &blob_refs,
        kzg_cell_proofs.to_vec(),
        block,
        &chain.kzg,
        &chain.spec,
    )
    .discard_timer_on_break(&mut timer)?;
    drop(timer);
    Ok(sidecars)
}

/// Implemented on types that can be converted into a `ExecutionPendingBlock`.
///
/// Used to allow functions to accept blocks at various stages of verification.
pub trait IntoExecutionPendingBlock<T: BeaconChainTypes>: Sized {
    #[instrument(skip_all, level = "debug")]
    fn into_execution_pending_block(
        self,
        block_root: Hash256,
        chain: &Arc<BeaconChain<T>>,
        notify_execution_layer: NotifyExecutionLayer,
    ) -> Result<ExecutionPendingBlock<T>, BlockError> {
        self.into_execution_pending_block_slashable(block_root, chain, notify_execution_layer)
            .inspect(|execution_pending| {
                // Supply valid block to slasher.
                if let Some(slasher) = chain.slasher.as_ref() {
                    slasher.accept_block_header(execution_pending.block.signed_block_header());
                }
            })
            .map_err(|slash_info| process_block_slash_info::<_, BlockError>(chain, slash_info))

pub fn blobs_to_data_column_sidecars<E: EthSpec>(
    blobs: &[&Blob<E>],
    cell_proofs: Vec<KzgProof>,
    block: &SignedBeaconBlock<E>,
    kzg: &Kzg,
    spec: &ChainSpec,
) -> Result<DataColumnSidecarList<E>, DataColumnSidecarError> {
    if blobs.is_empty() {
        return Ok(vec![]);
    }

    let kzg_commitments = block
        .message()
        .body()
        .blob_kzg_commitments()
        .map_err(|_err| DataColumnSidecarError::PreDeneb)?;
    let kzg_commitments_inclusion_proof = block.message().body().kzg_commitments_merkle_proof()?;
    let signed_block_header = block.signed_block_header();

    let proof_chunks = cell_proofs
        .chunks_exact(E::number_of_columns())
        .collect::<Vec<_>>();

    // NOTE: assumes blob sidecars are ordered by index
    let zipped: Vec<_> = blobs.iter().zip(proof_chunks).collect();
    let blob_cells_and_proofs_vec = zipped
        .into_par_iter()
        .map(|(blob, proofs)| {
            let blob = blob.as_ref().try_into().map_err(|e| {
                KzgError::InconsistentArrayLength(format!(
                    "blob should have a guaranteed size due to FixedVector: {e:?}"
                ))
            })?;

            kzg.compute_cells(blob).and_then(|cells| {
                let proofs = proofs.try_into().map_err(|e| {
                    KzgError::InconsistentArrayLength(format!(
                        "proof chunks should have exactly `number_of_columns` proofs: {e:?}"
                    ))
                })?;
                Ok((cells, proofs))
            })
        })
        .collect::<Result<Vec<_>, KzgError>>()?;

    build_data_column_sidecars(
        kzg_commitments.clone(),
        kzg_commitments_inclusion_proof,
        signed_block_header,
        blob_cells_and_proofs_vec,
        spec,
    )
    .map_err(DataColumnSidecarError::BuildSidecarFailed)
}

